slides.content:
You can now bootstrap an Angular app without any NgModule! Use `bootstrapApplication()` in `main.ts`:

```typescript
import { bootstrapApplication } from '@angular/platform-browser';
import { AppComponent } from './app/app.component';

bootstrapApplication(AppComponent);
```

`AppComponent` can be standalone, and you import providers (like `provideRouter`) directly in the bootstrap call.

slides.codeSnippet:
import { Routes } from '@angular/router';

export const routes: Routes = [
  {
    path: 'products',
    loadComponent: () => import('./products/product-list.component').then(m => m.ProductListComponent)
  }
];

// main.ts
bootstrapApplication(AppComponent, {
  providers: [provideRouter(routes)]
});
